// Parse the AI output JSON
const rawOutput = $input.first().json.output;
let parsed;
try {
  // Try to extract JSON from the output (handle markdown code blocks)
  const jsonMatch = rawOutput.match(/```json\n?([\s\S]*?)\n?```/) || rawOutput.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : rawOutput;
  parsed = JSON.parse(jsonStr);
} catch (e) {
  parsed = {
    alertLevel: 'ERROR',
    summary: { totalActive: 0, critical: 0, warning: 0, safe: 0, overallHealth: 'ERROR' },
    criticalAlerts: [],
    warningAlerts: [],
    staffWorkloadAnalysis: [],
    executiveSummaryId: 'Gagal memproses analisis. Silakan coba lagi.',
    executiveSummaryEn: 'Failed to process analysis. Please try again.',
    notificationMessages: {
      executive: { subject: '⚠️ Error Sistem Peringatan Dini', body: 'Terjadi kesalahan dalam memproses data. Silakan periksa secara manual.' },
      officer: { subject: '⚠️ Error Sistem Peringatan Dini', body: 'Terjadi kesalahan dalam memproses data.' }
    }
  };
}

// Determine if we need to send notifications
const hasAlerts = (parsed.summary?.critical > 0) || (parsed.summary?.warning > 0);
const alertLevel = parsed.alertLevel || 'AMAN';

// Build rich email body for executive
let execBody = `🏦 SISTEM PERINGATAN DINI SLA - TRADE OPERATIONS\n`;
execBody += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;
execBody += `📅 Waktu: ${parsed.timestamp || new Date().toISOString()}\n`;
execBody += `🚦 Status: ${alertLevel}\n`;
execBody += `📊 Kesehatan Operasi: ${parsed.summary?.overallHealth || 'N/A'}\n\n`;
execBody += `═══ RINGKASAN ═══\n`;
execBody += `• Total L/C Aktif: ${parsed.summary?.totalActive || 0}\n`;
execBody += `• 🔴 Kritis: ${parsed.summary?.critical || 0}\n`;
execBody += `• 🟡 Peringatan: ${parsed.summary?.warning || 0}\n`;
execBody += `• ✅ Aman: ${parsed.summary?.safe || 0}\n\n`;

if (parsed.criticalAlerts?.length > 0) {
  execBody += `═══ 🔴 ALERT KRITIS ═══\n\n`;
  parsed.criticalAlerts.forEach((a, i) => {
    execBody += `${i+1}. ${a.urn} [${a.transactionType}]\n`;
    execBody += `   Status: ${a.status} | Staf: ${a.assignedTo} | Officer: ${a.approvedBy || '-'}\n`;
    execBody += `   Elapsed: ${a.elapsedMinutes}m / SLA: ${a.slaMaxMinutes}m (BREACH ${a.breachMinutes}m)\n`;
    execBody += `   Tahap: ${a.currentStage}\n`;
    execBody += `   Bottleneck: ${a.bottleneck}\n`;
    execBody += `   Akar Penyebab: ${a.rootCause}\n`;
    execBody += `   💡 Rekomendasi: ${a.recommendation}\n\n`;
  });
}

if (parsed.warningAlerts?.length > 0) {
  execBody += `═══ 🟡 PERINGATAN ═══\n\n`;
  parsed.warningAlerts.forEach((a, i) => {
    execBody += `${i+1}. ${a.urn} [${a.transactionType}]\n`;
    execBody += `   Status: ${a.status} | Staf: ${a.assignedTo}\n`;
    execBody += `   Elapsed: ${a.elapsedMinutes}m / SLA: ${a.slaMaxMinutes}m (Sisa: ${a.remainingMinutes}m)\n`;
    execBody += `   Tahap: ${a.currentStage}\n`;
    execBody += `   Faktor Risiko: ${a.riskFactor}\n`;
    execBody += `   💡 Rekomendasi: ${a.recommendation}\n\n`;
  });
}

if (parsed.staffWorkloadAnalysis?.length > 0) {
  execBody += `═══ 👥 ANALISIS BEBAN KERJA STAF ═══\n\n`;
  parsed.staffWorkloadAnalysis.forEach(s => {
    const overloadIcon = s.isOverloaded ? '🔴' : '✅';
    execBody += `${overloadIcon} ${s.name} (${s.section}): ${s.activeCount} aktif, ${s.atRiskCount} berisiko\n`;
    if (s.isOverloaded) execBody += `   ⚠️ ${s.recommendation}\n`;
  });
  execBody += `\n`;
}

execBody += `═══ RINGKASAN EKSEKUTIF ═══\n`;
execBody += `🇮🇩 ${parsed.executiveSummaryId || ''}\n\n`;
execBody += `🇬🇧 ${parsed.executiveSummaryEn || ''}\n`;

// Build officer-specific body
let officerBody = parsed.notificationMessages?.officer?.body || execBody;

return [{
  json: {
    hasAlerts,
    alertLevel,
    parsed,
    executiveEmail: {
      subject: parsed.notificationMessages?.executive?.subject || `🚨 ${alertLevel} Peringatan SLA - ${new Date().toISOString().split('T')[0]}`,
      body: execBody
    },
    officerEmail: {
      subject: parsed.notificationMessages?.officer?.subject || `⚠️ ${alertLevel} L/C Perlu Perhatian - ${new Date().toISOString().split('T')[0]}`,
      body: officerBody
    },
    slackMessage: execBody,
    webhookResponse: parsed
  }
}];

// Input: parsed object from "Parse & Format Messages" node
const d = $input.first().json.parsed;
const ts = d.timestamp ? d.timestamp.substring(0, 16).replace('T', ' ') : new Date().toISOString().substring(0, 16).replace('T', ' ');

const levelIcon = { KRITIS: '🔴', PERINGATAN: '🟡', AMAN: '🟢', ERROR: '⚠️' };
const icon = levelIcon[d.alertLevel] || '⚪';

let msg = `${icon} *SLA ALERT — Trade Ops*\n`;
msg += `🕐 ${ts}\n`;
msg += `Status: *${d.alertLevel}* | Health: ${d.summary?.overallHealth || '-'}\n`;
msg += `📊 Aktif: ${d.summary?.totalActive || 0} | 🔴 ${d.summary?.critical || 0} | 🟡 ${d.summary?.warning || 0} | ✅ ${d.summary?.safe || 0}\n\n`;

if (d.criticalAlerts?.length > 0) {
  msg += `*🔴 KRITIS:*\n`;
  d.criticalAlerts.slice(0, 3).forEach(a => {
    msg += `• ${a.urn} (${a.transactionType}) — ${a.assignedTo}\n`;
    msg += `  ${a.elapsedMinutes}m / ${a.slaMaxMinutes}m, breach +${a.breachMinutes}m\n`;
    msg += `  ➤ ${a.recommendation?.substring(0, 80)}...\n`;
  });
  if (d.criticalAlerts.length > 3) msg += `  _...+${d.criticalAlerts.length - 3} lainnya_\n`;
  msg += `\n`;
}

if (d.warningAlerts?.length > 0) {
  msg += `*🟡 PERINGATAN:*\n`;
  d.warningAlerts.slice(0, 2).forEach(a => {
    msg += `• ${a.urn} (${a.transactionType}) — sisa ${a.remainingMinutes}m\n`;
  });
  if (d.warningAlerts.length > 2) msg += `  _...+${d.warningAlerts.length - 2} lainnya_\n`;
  msg += `\n`;
}

const overloaded = d.staffWorkloadAnalysis?.filter(s => s.isOverloaded) || [];
if (overloaded.length > 0) {
  msg += `*👥 Staf Overload:* ${overloaded.map(s => s.name).join(', ')}\n`;
}

return [{ json: { ...$input.first().json, whatsappMessage: msg.trim() } }];
